# Update POS Frontend: VIP Popup Stats + Browser Notifications
# Run from your dashboard folder (where manage.py is)

$base64 = ""
$bytes = [System.Convert]::FromBase64String($base64)
$py = [System.Text.Encoding]::UTF8.GetString($bytes)

# Backup
$ts = Get-Date -Format "yyyyMMdd_HHmmss"
Copy-Item -Path "templates\sales\pos.html" -Destination "templates\sales\pos.html.backup.$ts" -ErrorAction SilentlyContinue

# Write and run Python script
[IO.File]::WriteAllText("_temp_pos.py", $py)
python "_temp_pos.py"
Remove-Item "_temp_pos.py"

Write-Host "✅ Done! pos.html updated with VIP popup stats + browser notifications" -ForegroundColor Green
